'use strict';
const $ = (s) => document.querySelector(s);
const $$ = (s) => [...document.querySelectorAll(s)];
const money = n => `₹${n.toLocaleString('en-IN')}`;
const colours = [ {id:'denim',name:'Blue jean day',hex:'#6686a0',light:'#95aabd'}, {id:'rose',name:'Rosy outlook',hex:'#c98791',light:'#e2b4af'}, {id:'sage',name:'Garden green',hex:'#839679',light:'#b4bea0'}, {id:'butter',name:'Butter together',hex:'#c3a96b',light:'#e0cd9b'}, {id:'ink',name:'After hours',hex:'#4e5a61',light:'#83939b'} ];
const bags = [
 {id:'tote',name:'The Everyday Tote',tag:'THE CLOSET CLASSIC',category:'everyday',price:499,bg:'#e7e9dd',colour:'denim',pattern:'plain',description:'For big plans & all the little things.',fabric:'Lovely in denim or sturdy cotton'},
 {id:'mini',name:'The Little Mood',tag:'SMALL BAG, BIG ENERGY',category:'mini',price:399,bg:'#f0dce0',colour:'rose',pattern:'patch',description:'Phone, keys, a little main character.',fabric:'Made for your favourite fabric mix'},
 {id:'shoulder',name:'The Daydreamer',tag:'YOUR NEW EVERYWHERE BAG',category:'shoulder',price:599,bg:'#e7e9cf',colour:'sage',pattern:'plain',description:'An over-the-shoulder kind of love.',fabric:'Try cotton, corduroy or sturdy blends'},
 {id:'bucket',name:'The Bucket List',tag:'A LITTLE DIFFERENT',category:'everyday',price:549,bg:'#eee2cc',colour:'butter',pattern:'stripe',description:'Room for all your beautiful chaos.',fabric:'Good with denim & heavier cotton'}
];
let svgId=0, step=0, selectedColour='denim', photoURL=null, isSaving=false;
const STORAGE_KEY='rebag-makes-v1';
let storageAvailable=true, saved=[];
try { const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]'); if(Array.isArray(raw)) saved=raw.filter(validMake); } catch { storageAvailable=false; }
function validMake(m){return m && typeof m.id==='string' && typeof m.created==='string' && bags.some(b=>b.id===m.shape) && colours.some(c=>c.id===m.colour) && ['plain','patch','stripe'].includes(m.pattern) && ['matching','contrast','long'].includes(m.strap) && typeof m.notes==='string' && typeof m.initials==='string' && Number.isFinite(m.total);}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function bagSVG(shape='tote',colour='denim',pattern='plain',initials='',strap='matching'){
 const c=colours.find(c=>c.id===colour)||colours[0]; const id=`bag${svgId++}`; const handle=strap==='contrast'?'#c3a16e':c.hex;
 const shapes={tote:'M73 128 L247 128 L266 284 Q266 301 248 303 L72 303 Q54 301 54 284 Z',mini:'M67 172 Q160 145 253 172 L265 277 Q265 298 244 301 L76 301 Q55 298 55 277 Z',shoulder:'M56 158 Q160 201 264 158 L259 261 Q252 303 210 308 L110 308 Q68 303 61 261 Z',bucket:'M79 145 Q160 155 241 145 L258 279 Q252 307 160 311 Q68 307 62 279 Z'};
 const path=shapes[shape]||shapes.tote; const top=shape==='tote'?128:shape==='mini'?174:shape==='bucket'?148:170;
 const handles=shape==='shoulder'?`<path d="M80 173 C48 10 270 10 241 173"/>`:shape==='mini'?`<path d="M113 164 C108 86 212 86 207 164"/>`:`<path d="M105 ${top+8} L105 85 C105 28 215 28 215 85 L215 ${top+8}"/>`;
 const panels=pattern==='patch'?`<path d="M38 210 L160 215 L156 335 L30 330Z" fill="${c.light}"/><path d="M160 125 L290 125 L285 230 L158 217Z" fill="#d6bc94"/><path d="M158 215 L285 229 L290 335 L156 335Z" fill="${c.hex}"/><path d="M160 120 L158 325 M45 210 L278 228" stroke="#fff4d2" stroke-width="1.4" stroke-dasharray="4 3"/>`:pattern==='stripe'?`<path d="M92 120 L92 330 M140 120 L140 330 M188 120 L188 330 M236 120 L236 330" stroke="${c.light}" stroke-width="22"/>`:'';
 const pocket=shape==='tote'?`<path d="M112 193 L208 193 L205 252 Q160 268 115 252Z" fill="${c.light}" stroke="#344b4522"/><path d="M117 199 L203 199 L200 247 Q160 260 120 247Z" fill="none" stroke="#f4e6c7" stroke-dasharray="3 3" stroke-width="1.2"/>`:'';
 const extra=shape==='bucket'?'<path d="M81 162 Q160 180 240 162 M120 168 Q125 208 161 177 Q191 207 200 172 M159 181 L146 235 M164 181 L177 225" stroke="#ebdfc4" stroke-width="3" fill="none"/>':'';
 const long=strap==='long'?`<path d="M68 215 C-15 -5 344 -5 252 215" fill="none" stroke="${handle}" stroke-width="12"/><path d="M68 215 C-15 -5 344 -5 252 215" fill="none" stroke="#f5e5c6" stroke-width="1" stroke-dasharray="4 4"/>`:'';
 return `<svg viewBox="0 0 320 345" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><clipPath id="${id}-clip"><path d="${path}"/></clipPath><pattern id="${id}-weave" width="5" height="5" patternUnits="userSpaceOnUse"><path d="M0 0L5 5M-1 4L1 6M4 -1L6 1" stroke="#fff" stroke-opacity=".17" stroke-width=".6"/><path d="M0 5L5 0" stroke="#183430" stroke-opacity=".09" stroke-width=".6"/></pattern></defs><ellipse cx="160" cy="319" rx="109" ry="10" fill="#263f2910"/>${long}<g fill="none" stroke="${handle}" stroke-width="17" stroke-linejoin="round">${handles}</g><g fill="none" stroke="#eee1c2" stroke-width="1.2" stroke-dasharray="3 3">${handles}</g><path d="${path}" fill="${c.hex}" stroke="#263f2926" stroke-width="2"/><g clip-path="url(#${id}-clip)">${panels}<rect x="40" y="120" width="245" height="195" fill="url(#${id}-weave)"/><path d="${path}" fill="none" stroke="#f6e8ca" stroke-width="12" stroke-opacity=".3"/><path d="${path}" fill="none" stroke="#eee2c6" stroke-width="1.5" stroke-dasharray="4 3" transform="translate(160 215) scale(.93) translate(-160 -215)"/>${pocket}</g>${extra}<path d="M75 ${top+5} Q160 ${top+13} 245 ${top+5}" stroke="#2c403236" fill="none" stroke-width="2"/><rect x="211" y="257" width="41" height="18" rx="1" fill="#eee7d2" transform="rotate(-3 230 265)"/><text x="231" y="269" font-family="sans-serif" font-size="7" font-weight="700" letter-spacing=".5" text-anchor="middle" fill="#3d513e">rebag ✳</text>${initials?`<text x="160" y="${shape==='tote'?235:254}" fill="#fff5dc" font-family="Georgia,serif" font-size="23" text-anchor="middle">${esc(initials)}</text>`:''}</svg>`;
}
function renderProducts(filter='all'){
 $('#products').innerHTML=bags.filter(b=>filter==='all'||b.category===filter).map(b=>`<article class="product-card"><button class="product-art" style="--card-bg:${b.bg}" data-bag="${b.id}" aria-label="Customize ${b.name}"><span class="product-label">${b.tag}</span>${bagSVG(b.id,b.colour,b.pattern)}<span class="product-arrow">↗</span></button><div class="product-title"><h3>${b.name}</h3><span>from ${money(b.price)}</span></div><p>${b.description}</p><div class="product-caption"><span class="colour-dot" style="background:${colours.find(c=>c.id===b.colour).hex}"></span>${b.fabric}</div></article>`).join('');
}
function openDialog(id){$('#'+id).showModal();document.body.classList.add('modal-open');}
function closeDialog(id){$('#'+id).close();if(!document.querySelector('dialog[open]')) document.body.classList.remove('modal-open');}
function updateCount(){$('#saved-count').textContent=saved.length;}
function startDesign(id='tote'){
 const bag=bags.find(b=>b.id===id)||bags[0]; $('#design-form').reset(); $('#bag-shape').value=bag.id;selectedColour=bag.colour;$('#fabric-pattern').value=bag.pattern; $(`input[name=colour][value=${bag.colour}]`).checked=true; step=0;isSaving=false;clearPhoto();$('#form-error').textContent='';showStep();updatePreview();openDialog('studio');
}
function design(){return {shape:$('#bag-shape').value,colour:selectedColour,pattern:$('#fabric-pattern').value,strap:$('#strap').value,initials:$('#initials').value.toUpperCase(),notes:$('#design-notes').value.trim(),material:$('#material').value,garments:Number($('#garments').value),handover:$('#handover').value,hasPhoto:!!photoURL};}
function estimate(d){return bags.find(b=>b.id===d.shape).price+(d.strap==='contrast'?80:d.strap==='long'?120:0)+(d.pattern==='patch'?100:0);}
function updatePreview(){const d=design();$('#live-bag').innerHTML=bagSVG(d.shape,d.colour,d.pattern,d.initials,d.strap);$('#estimate').textContent=money(estimate(d));$('#preview-summary').textContent=bags.find(b=>b.id===d.shape).name;}
function showStep(){ $$('.form-step').forEach((e,i)=>e.hidden=i!==step);$$('.studio-progress span').forEach((e,i)=>e.classList.toggle('current',i===step));$('#back').hidden=step===0;$('#next').textContent=['Your clothes →','Review my make →','Save demo request ↗'][step];$('#form-error').textContent='';if(step===2) renderReview(); }
const row=(label,value)=>`<div class="review-row"><span>${esc(label)}</span><span>${esc(value)}</span></div>`;
function renderReview(){const d=design(),bag=bags.find(b=>b.id===d.shape);$('#review-content').innerHTML=row('Bag',bag.name)+row('Colour mood',colours.find(c=>c.id===d.colour).name)+row('Fabric',`${$('#material').selectedOptions[0].text} · ${d.garments} garment(s)`)+row('Details',`${$('#fabric-pattern').selectedOptions[0].text}${d.initials?' · '+d.initials:''}`)+row('Handover preference',d.handover)+row('Garment photo',d.hasPhoto?'Previewed locally · not saved':'Not added')+(d.notes?`<p class="review-notes"><strong>Your idea:</strong> ${esc(d.notes)}</p>`:'');$('#quote').innerHTML=row('Base making fee',money(bag.price))+row('Patchwork detail',d.pattern==='patch'?money(100):'Included')+row('Handles / strap',d.strap==='matching'?'Included':money(d.strap==='contrast'?80:120))+row('Delivery','Not quoted')+row('Illustrative subtotal',money(estimate(d)));}
function validateStep(){const fields=step===0?['#initials']:step===1?['#garments','#condition']:['#demo-consent'];for(const selector of fields){const el=$(selector);if(!el.checkValidity()){el.reportValidity();return false;}}return true;}
function clearPhoto(){if(photoURL) URL.revokeObjectURL(photoURL);photoURL=null;$('#photo-preview').hidden=true;$('#photo-preview').removeAttribute('src');$('#photo-status').textContent='';$('#cloth-photo').value='';}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function saveMake(){if(isSaving)return;isSaving=true;const d=design(),item={...d,id:'RB-'+crypto.randomUUID().slice(0,8).toUpperCase(),created:new Date().toISOString(),total:estimate(d),status:'Demo request — not submitted'};const nextSaved=[item,...saved];let persisted=storageAvailable;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(nextSaved));storageAvailable=true;persisted=true;}catch{storageAvailable=false;persisted=false;}saved=nextSaved;updateCount();closeDialog('studio');clearPhoto();renderMakes(true,persisted);openDialog('makes');}
function renderMakes(success=false,persisted=true){
 const list=$('#makes-list');list.innerHTML=(success?`<div class="success-note"><strong>Your next chapter is taking shape. ✳</strong><br>${persisted?'Demo saved on this device.':'Browser storage is unavailable. Download your brief now; this request will disappear when the page closes.'} No real order has been placed.</div>`:'')+(saved.length?saved.map(m=>{const b=bags.find(b=>b.id===m.shape);return `<article class="saved-make"><div class="saved-art">${bagSVG(m.shape,m.colour,m.pattern,m.initials,m.strap)}</div><div><span class="saved-id">${esc(m.id)} · DEMO ONLY</span><h3>${b.name}</h3><p>${esc(new Date(m.created).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}))} · ${money(m.total)} illustrative subtotal<br>Saved locally. Awaiting no real fulfilment.</p><div class="saved-actions"><button data-download="${esc(m.id)}">Download design brief ↓</button><button data-remove="${esc(m.id)}">Remove</button></div></div></article>`;}).join(''):`<div class="empty-makes"><span>✳</span><h3>A little room for new stories.</h3><p>Your saved demo designs will live here.<br>Ready to give an old favourite a second act?</p><button class="button" id="empty-start">Make my first bag ↗</button></div>`);
}
function downloadMake(id){const m=saved.find(m=>m.id===id);if(!m)return;const {hasPhoto,...brief}=m;const output={brand:'Rebag — concept prototype',...brief,bagName:bags.find(b=>b.id===m.shape).name,currency:'INR',priceNote:'Illustrative making fee. Delivery excluded. Subject to fabric review and final quote.',garmentPhoto:hasPhoto?'Previewed in browser only; not included in brief':'Not provided',notice:'No real order, payment or pickup. Share this brief manually if you choose.'};const url=URL.createObjectURL(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`rebag-${m.id}-design.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your design brief is ready to keep.');}
$('#hero-bag-one').innerHTML=bagSVG('tote','denim','plain');$('#hero-bag-two').innerHTML=bagSVG('mini','rose','patch');$('#banner-bag').innerHTML=bagSVG('bucket','butter','patch','YOU');
$('#bag-shape').innerHTML=bags.map(b=>`<option value="${b.id}">${b.name} · from ${money(b.price)}</option>`).join('');
$('#swatches').innerHTML=colours.map((c,i)=>`<label class="swatch" title="${c.name}"><input type="radio" name="colour" value="${c.id}" aria-label="${c.name}" ${i===0?'checked':''}><span style="--swatch:${c.hex}"></span></label>`).join('');
renderProducts();updateCount();
document.addEventListener('click',e=>{
 const start=e.target.closest('[data-start]'),bag=e.target.closest('[data-bag]'),close=e.target.closest('[data-close]'),filter=e.target.closest('[data-filter]'),download=e.target.closest('[data-download]'),remove=e.target.closest('[data-remove]');
 if(start)startDesign();if(bag)startDesign(bag.dataset.bag);if(close)closeDialog(close.dataset.close);
 if(filter){$$('[data-filter]').forEach(b=>{const active=b===filter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});renderProducts(filter.dataset.filter);}
 if(download)downloadMake(download.dataset.download);
 if(remove){const remaining=saved.filter(m=>m.id!==remove.dataset.remove);try{localStorage.setItem(STORAGE_KEY,JSON.stringify(remaining));saved=remaining;renderMakes();updateCount();toast('Demo design removed.');}catch{toast('Could not update browser storage. Your saved designs are unchanged.');}}
 if(e.target.closest('#empty-start')){closeDialog('makes');startDesign();}
});
$('#saved').addEventListener('click',()=>{renderMakes(false,storageAvailable);openDialog('makes');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){const open=document.querySelector('dialog[open]');if(open){e.preventDefault();closeDialog(open.id);}}});
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');if(d.id==='studio')clearPhoto();});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id);}});});
$('#design-form').addEventListener('input',e=>{if(e.target.name==='colour')selectedColour=e.target.value;if(e.target.id==='initials')e.target.value=e.target.value.replace(/[^a-z]/gi,'').toUpperCase();updatePreview();});
$('#design-form').addEventListener('change',updatePreview);
$('#design-form').addEventListener('submit',e=>{e.preventDefault();$('#next').click();});
$('#next').addEventListener('click',()=>{if(!validateStep())return;if(step<2){step++;showStep();$('.form-step:not([hidden]) h3').setAttribute('tabindex','-1');$('.form-step:not([hidden]) h3').focus();}else saveMake();});
$('#back').addEventListener('click',()=>{if(step>0){step--;showStep();}});
$('#cloth-photo').addEventListener('change',()=>{const f=$('#cloth-photo').files[0];if(!f){clearPhoto();return;}if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024){clearPhoto();$('#photo-status').textContent='Choose a JPG, PNG or WebP image smaller than 5 MB.';return;}if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(f);const img=$('#photo-preview');img.onerror=()=>{clearPhoto();$('#photo-status').textContent='This image could not be read. Please choose another photo.';};img.src=photoURL;img.hidden=false;$('#photo-status').textContent='Photo added for this preview. It stays on your device.';});
